package dev.droidwrt.panel;
import android.app.*;import android.os.*;import android.content.*;import android.hardware.Camera;import android.view.*;import android.widget.*;import android.graphics.Color;
import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import java.util.*;
@SuppressWarnings("deprecation")
public class ScanActivity extends Activity implements SurfaceHolder.Callback {
 Camera camera;SurfaceView surface;boolean done=false,decoding=false;HandlerThread thread;Handler worker;long lastFrame=0;
 @Override public void onCreate(Bundle b){MainActivity.applySystemTheme(this);super.onCreate(b);MainActivity.applySystemTheme(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(MainActivity.BG);TextView label=new TextView(this);label.setText("QR-код VPN");label.setTextColor(MainActivity.FG);label.setTextSize(24);label.setPadding(28,32,28,24);root.addView(label);surface=new SurfaceView(this);root.addView(surface,new LinearLayout.LayoutParams(-1,0,1));TextView hint=new TextView(this);hint.setText("Наведите камеру на QR-код конфигурации");hint.setTextColor(MainActivity.MUTED);hint.setPadding(28,24,28,24);root.addView(hint);Button cancel=new Button(this);cancel.setText("Отмена");cancel.setAllCaps(false);cancel.setOnClickListener(v->finish());root.addView(cancel);setContentView(root);surface.getHolder().addCallback(this);thread=new HandlerThread("QR");thread.start();worker=new Handler(thread.getLooper());}
 public void surfaceCreated(SurfaceHolder holder){startCamera(holder);}
 void startCamera(SurfaceHolder holder){if(done||camera!=null)return;try{camera=Camera.open();Camera.Parameters p=camera.getParameters();List<String> modes=p.getSupportedFocusModes();if(modes!=null&&modes.contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))p.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);Camera.Size best=null;for(Camera.Size s:p.getSupportedPreviewSizes()){if(s.width<=1280&&(best==null||s.width>best.width))best=s;}if(best!=null)p.setPreviewSize(best.width,best.height);camera.setParameters(p);camera.setDisplayOrientation(90);camera.setPreviewDisplay(holder);camera.setPreviewCallback((data,cam)->{if(done||decoding||SystemClock.elapsedRealtime()-lastFrame<350)return;lastFrame=SystemClock.elapsedRealtime();decoding=true;Camera.Size size=cam.getParameters().getPreviewSize();byte[] frame=data.clone();worker.post(()->{try{PlanarYUVLuminanceSource src=new PlanarYUVLuminanceSource(frame,size.width,size.height,0,0,size.width,size.height,false);Map<DecodeHintType,Object> hints=new EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.POSSIBLE_FORMATS,Collections.singletonList(BarcodeFormat.QR_CODE));hints.put(DecodeHintType.TRY_HARDER,Boolean.TRUE);Result result=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(src)),hints);done=true;runOnUiThread(()->{setResult(RESULT_OK,new Intent().putExtra("profile",result.getText()));finish();});}catch(NotFoundException e){}finally{decoding=false;}});});camera.startPreview();}catch(Exception e){release();LinearLayout error=new LinearLayout(this);error.setOrientation(1);error.setPadding(40,70,40,40);error.setBackgroundColor(MainActivity.BG);TextView message=new TextView(this);message.setText("Камера недоступна\n\nМожно импортировать файл или вставить ссылку.");message.setTextSize(20);message.setTextColor(MainActivity.FG);error.addView(message);Button close=new Button(this);close.setText("Назад");close.setOnClickListener(v->finish());error.addView(close);setContentView(error);}}
 public void surfaceChanged(SurfaceHolder h,int f,int w,int t){}public void surfaceDestroyed(SurfaceHolder h){release();}
 void release(){if(camera!=null){camera.setPreviewCallback(null);camera.stopPreview();camera.release();camera=null;}}
 @Override protected void onPause(){release();super.onPause();}
 @Override protected void onResume(){super.onResume();if(surface!=null&&surface.getHolder().getSurface().isValid())startCamera(surface.getHolder());}
 @Override protected void onDestroy(){release();if(thread!=null)thread.quitSafely();super.onDestroy();}
}
